def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_def = 0
    opp_def = 0
    for a, b in history:
        if a == 'D':
            my_def += 1
        if b == 'D':
            opp_def += 1

    if opp_def == n:
        return 'D'

    last_my, last_opp = history[-1]

    if n < 85:
        if last_opp == 'D':
            if my_def >= opp_def:
                return 'C'
            return 'D'
        else:
            return 'C'

    if opp_def == 0:
        if my_def == 0:
            return 'D'
        else:
            first_d = n
            for i in range(n):
                if history[i][0] == 'D':
                    first_d = i
                    break
            if n == first_d + 1:
                return 'C'
            return 'D'

    if last_opp == 'D':
        if my_def >= opp_def:
            return 'C'
        return 'D'
    else:
        retaliated = False
        for i in range(n - 1):
            if history[i][0] == 'D' and history[i+1][1] == 'D':
                retaliated = True
                break
        if not retaliated and my_def > 0:
            if rng.random() < 0.7:
                return 'D'
        return 'C'
